  Line: 'root = Stack([Line("Average wait", [Series("n = 5", [{x:0,y:1},{x:1,y:2},{x:2,y:1.5}]), Series("n = 30", [0.8, 1.2, 1])], "Trial", "Wait (min)")])',
  Area: 'root = Stack([Line("Cumulative study", [Series("Reading", [1,2,4,5]), Series("Practice", [0,1,2,4])], "Day", "Time (h)", true)])',
  Scatter: 'root = Stack([Scatter("Practice and score", [{x:1,y:45},{x:3,y:65},{x:4,y:60},{x:5,y:80}], "Practice (h)", "Score (%)", true)])',
  Donut: 'root = Stack([Donut("Study time", ["Reading", "Practice", "Review"], [2, 3, 1], null, "h")])',
  Distribution: 'root = Stack([Distribution("Wait density", [{x:0,y:0},{x:1,y:0.5},{x:2,y:1},{x:3,y:0.5},{x:4,y:0}], [{from:1,to:2.5},{from:2,to:3}], "Wait (min)", true)])',
  Panel: 'root = Stack([Panel("This week", [Stat("Tasks due", 4), Progress("Lectures watched", 7, 12)])])',
  Columns: 'root = Stack([Columns([Panel("Reading", [Stat("Time", 2, "h")]), Panel("Practice", [Stat("Time", 3, "h")])])])',
