  Stat: 'root = Stack([Stat("Mean wait", 1.03, "min", "400 trials"), Stat("Spread", 0.19, "min")])',
  Badge: 'root = Stack([Badge("Ready", "success"), Badge("Due soon", "warning")])',
  Progress: 'root = Stack([Progress("Practice questions", 7, 12)])',
  Tabs: 'root = Stack([Tabs([Tab("Population", [Text("Individual waits are skewed.")]), Tab("Averages", [Text("Sample means are less spread out.")])])])',
